mapper.select:
SELECT * FROM attribute_values WHERE attr_id IN
#{attrId}
ORDER BY attr_id ASC, sort ASC

SELECT EXISTS(
    SELECT 1 FROM spu_basic_attr_values WHERE attr_value_id = #{attrValueId}
)

SELECT EXISTS(
    SELECT 1 FROM sku_sale_attr_values sav
    INNER JOIN sku ON sku.id = sav.sku_id AND sku.is_deleted = 0
    WHERE sav.attr_value_id = #{attrValueId}
)
